SELECT

FROM content_audit_log
WHERE 1=1

    AND audited_at >= #{startTime}


    AND audited_at <= #{endTime}

ORDER BY audited_at DESC

SELECT

FROM content_audit_log
WHERE 1=1

    AND auditor_id = #{auditorId}


    AND audited_at >= #{startTime}


    AND audited_at <= #{endTime}

ORDER BY audited_at DESC

SELECT COALESCE(JSON_UNQUOTE(JSON_EXTRACT(ai_audit_result, '$.riskType')), 'unknown') as violationType, COUNT(*) as count FROM content_audit_log WHERE audit_status = 2
AND audited_at >= #{startTime}
AND audited_at <= #{endTime}
GROUP BY violationType ORDER BY count DESC

SELECT DATE_FORMAT(audited_at, '%Y-%m-%d') as auditDate, COUNT(*) as totalCount, SUM(CASE WHEN audit_status = 1 THEN 1 ELSE 0 END) as approvedCount, SUM(CASE WHEN audit_status = 2 THEN 1 ELSE 0 END) as rejectedCount FROM content_audit_log WHERE 1=1
AND audited_at >= #{startTime}
AND audited_at <= #{endTime}
GROUP BY DATE_FORMAT(audited_at, '%Y-%m-%d') ORDER BY auditDate DESC

SELECT auditor_id as auditorId, COUNT(*) as totalCount, SUM(CASE WHEN audit_status = 1 THEN 1 ELSE 0 END) as approvedCount, SUM(CASE WHEN audit_status = 2 THEN 1 ELSE 0 END) as rejectedCount, AVG(process_time) as avgProcessTime FROM content_audit_log WHERE auditor_id IS NOT NULL
AND audited_at >= #{startTime}
AND audited_at <= #{endTime}
GROUP BY auditor_id ORDER BY totalCount DESC
